layers.vertex:
attribute vec3 aO; attribute float aT, aS; uniform float uTime; varying vec2 vP; varying float vU, vS;
    void main(){ float u = uTime - aT; if (u < 0. || u > 0.18){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(aO, 1.); mv.xyz += normalize(-mv.xyz)*.3; mv.xy += position.xy*.42;
      vP = position.xy*.42; vU = u; vS = aS; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform vec3 uDot, uDotL; varying vec2 vP; varying float vU, vS;
    void main(){
      vec2 p = vP; float lum = 0., hot = 0.;
        float t = vU/0.18, f = pow(1. - t, 1.3)*(vU < .033 ? 1.8 : 1.);
        vec2 cd = normalize(vec2(1., -.8 + .6*vS)); float s = dot(p, cd), n = dot(p, vec2(-cd.y, cd.x));
        float grow = 1. - pow(1. - clamp(vU/.04, 0., 1.), 3.), L = .3*grow;
        float prof = pow(max(0., 1. - abs(s)/max(L, .01)), .7), cw = .02*prof + .002;
        lum += exp(-pow(n/cw, 2.))*step(abs(s), L)*f*1.3;                        // short dry cut
        hot += exp(-pow(n/(cw*.3), 2.))*step(abs(s), L)*f;
        for (int j = 0; j < 5; j++){                                                // drops falling from the cut
          float fj = float(j), h = fract(sin(fj*37.7 + vS*11.)*4375.5);
          vec2 c = cd*(h - .5)*.4 + vec2((h - .5)*.08, -.5*t*t - .12*t*h);
          vec2 q = p - c; float sz = .016*(1. - .5*t);
          lum += exp(-(q.x*q.x)/(sz*sz) - (q.y*q.y)/(sz*sz*3.))*f*.9;
        }
      vec3 o = (uDot*lum + mix(uDot, uDotL, .7)*hot)*smoothstep(.42, .34, length(p));
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.); }
